#include <bits/stdc++.h>
#define inf 17446744073709551616ull
#define ull unsigned long long
using namespace std;

ull mod_value, dp_array[18][250005];
ull factorials[250005], inv_factorials[250005];
ull total_n, total_k;

ull fast_power(ull base, ull exp) {
    ull result = 1ULL;
    while (exp > 0) {
        if (exp & 1ULL) result = (result * base) % mod_value;
        base = (base * base) % mod_value;
        exp >>= 1ULL;
    }
    return result;
}

ull nCr(int a, int b) {
    return (((factorials[a] * inv_factorials[b]) % mod_value) * inv_factorials[a - b]) % mod_value;
}

ull compute() {
    int i, j, l;
    factorials[0] = 1ULL;
    for (i = 1; i <= total_n; i++) {
        factorials[i] = (factorials[i - 1] * (ull)i) % mod_value;
    }
    inv_factorials[total_n] = fast_power(factorials[total_n], mod_value - 2ULL);
    for (i = total_n - 1; i >= 0; i--) {
        inv_factorials[i] = (inv_factorials[i + 1] * (ull)(i + 1)) % mod_value;
    }
    for (i = 1; i <= total_n; i++) {
        dp_array[1][i] = inv_factorials[i];
    }
    ull answer = dp_array[1][total_n] * nCr(total_k, 1) % mod_value;
    int t = min(17, (int)total_k);
    for (i = 2; i <= t; i++) {
        for (j = total_n; j; j = (j - 1) & total_n) {
            for (l = j; l; l = (l - 1) & j) {
                dp_array[i][j] += dp_array[i - 1][j ^ l] * inv_factorials[l];
                if (dp_array[i][j] > inf) dp_array[i][j] %= mod_value;
            }
            dp_array[i][j] %= mod_value;
        }
        answer += dp_array[i][total_n] * nCr(total_k, i);
        answer %= mod_value;
    }
    answer *= factorials[total_n];
    answer %= mod_value;
    return answer;
}

int main() {
    cin >> total_n >> total_k >> mod_value;
    ull ans = fast_power(total_k, total_n);
    if (total_n & 1) {
        cout << ans << endl;
        return 0;
    }
    ans = (ans - compute() + mod_value) % mod_value;
    cout << ans << endl;
    return 0;
}
